"""Offline arithmetic, nesting and missing-data tests; no model or provider calls."""
from copy import deepcopy
import importlib.util
import json
from math import sqrt
from pathlib import Path
import tempfile
import unittest

import numpy as np
from scipy.stats import ttest_1samp


PATH = Path(__file__).resolve().parents[1]/"tools"/"analyze_targeted.py"
spec = importlib.util.spec_from_file_location("targeted_analysis", PATH)
analysis = importlib.util.module_from_spec(spec)
spec.loader.exec_module(analysis)


def fixture():
    """Nonconstant known forecasts; fixture is not generated by the analysis code."""
    seeds = list(range(20261027, 20261057))
    summary = {"status": "completed", "expected_calls": 3600,
               "history_results": {}, "history_paths": {}}
    checkpoints = {}
    for i, seed in enumerate(seeds):
        e = {"cells": [{"context": c, "source": s,
                         "estimate": .3333333333333333 if (c, s) == ("Y", "A") else .6666666666666666,
                         "lower": .1, "upper": .9}
                        for c in ("X", "Y", "Z") for s in ("A", "B", "C")]}
        p = deepcopy(e)
        pa = next(x for x in p["cells"] if (x["context"],x["source"]) == ("Y", "A"))
        pb = next(x for x in p["cells"] if (x["context"],x["source"]) == ("Y", "B"))
        pa["estimate"], pb["estimate"] = pb["estimate"], pa["estimate"]
        checkpoints[str(seed)] = {"E0": e, "P0": p}
        h = {"seed": seed, "status": "completed", "calls_attempted": 120,
             "expected_calls": 120, "branches": {}, "error": None}
        levels = {"P": .22+i*.004, "E": .2, "H": .17+i*.001,
                  "R0": .5, "R0rep": .5+(i-14.5)*.002}
        for arm, level in levels.items():
            rows = []
            for pid, bits, forecast, q in (
                ("Y100", {"A":1,"B":0,"C":0}, level, 21/242),
                ("Y011", {"A":0,"B":1,"C":1}, 1-level, 221/242)):
                rows.append({"profile_id":pid, "context":"Y", "signals":bits,
                             "actor_forecasts":{"A":forecast-.01,"B":forecast,"C":forecast+.01},
                             "probability":forecast,"oracle_probability":q,"cBR":(forecast-q)**2})
            h["branches"]["team_"+arm] = {
                "condition":"R0" if arm == "R0rep" else arm, "profiles":rows,
                "mean_cBR":sum(x["cBR"] for x in rows)/2, "complete":True}
        summary["history_results"][str(seed)] = h
    return summary, checkpoints, seeds


class StatisticalArithmeticTests(unittest.TestCase):
    def test_primary_formula_matches_independent_scipy_reference(self):
        values = [-.2, -.05, .01, .08, .1, .22, .31]
        actual = analysis.mean_test(values)
        reference = ttest_1samp(values, 0, alternative="two-sided")
        self.assertAlmostEqual(actual["t"], reference.statistic, places=13)
        self.assertAlmostEqual(actual["p_two_sided"], reference.pvalue, places=13)
        ci = reference.confidence_interval(.95)
        np.testing.assert_allclose(actual["ci95"], [ci.low, ci.high], atol=1e-14)
        self.assertEqual(actual["df"], 6)

    def test_zero_variance_is_labelled_not_perfect_population_certainty(self):
        for values in ([0]*30, [.1]*30):
            result = analysis.mean_test(values)
            self.assertEqual(result["inference_status"], "degenerate_sample_variance")
            self.assertIsNone(result["p_two_sided"])
            self.assertIsNone(result["t"])
            self.assertIsNone(result["ci95"])
            boot = analysis.bootstrap_mean(values)
            self.assertEqual(boot["status"], "degenerate_empirical_distribution")

    def test_one_history_and_empty_data_have_no_inference(self):
        for data in ([], [.3]):
            self.assertIsNone(analysis.mean_test(data)["p_two_sided"])
            self.assertIsNone(analysis.bootstrap_mean(data)["ci95"])

    def test_holm_retains_two_member_family_and_unavailable_test(self):
        np.testing.assert_allclose(analysis.holm_two([.03,.04]), [.06,.06])
        np.testing.assert_allclose(analysis.holm_two([.2,.01]), [.2,.02])
        self.assertEqual(analysis.holm_two([None,.03]), [1,.06])
        with self.assertRaises(ValueError): analysis.holm_two([.01])

    def test_missing_bounds_use_all_thirty_not_complete_case_denominator(self):
        result = analysis.missing_bounds([.2]*29)
        self.assertAlmostEqual(result["lower"], (5.8-1)/30)
        self.assertAlmostEqual(result["upper"], (5.8+1)/30)
        self.assertEqual(result["missing_n"], 1)
        self.assertEqual(analysis.missing_bounds([])["lower"], -1)
        self.assertEqual(analysis.missing_bounds([])["upper"], 1)

    def test_bootstrap_reproducible_and_resamples_histories(self):
        values = [-.12, -.01, .03, .04, .4]
        first = analysis.bootstrap_mean(values)
        self.assertEqual(first, analysis.bootstrap_mean(values))
        rng = np.random.default_rng(20261025)
        draws = np.asarray(values)[rng.integers(0,5,(10000,5))].mean(axis=1)
        np.testing.assert_array_equal(first["ci95"], np.quantile(draws,[.025,.975]))

    def test_sign_counts_keep_exact_zero_without_rounding(self):
        d = analysis.describe([-1e-15, 0, 1e-15])
        self.assertEqual((d["negative"],d["exact_zero"],d["positive"]), (1,1,1))

    def test_oracle_and_complement_are_known_fixed_fractions(self):
        self.assertAlmostEqual(analysis.posterior(analysis.REL["Y"], analysis.PROFILES["Y100"]),21/242,places=14)
        self.assertAlmostEqual(analysis.posterior(analysis.REL["Y"], analysis.PROFILES["Y011"]),221/242,places=14)


class TargetedContractTests(unittest.TestCase):
    def setUp(self):
        self.summary, self.checkpoints, self.seeds = fixture()

    def report(self):
        return analysis.analyze_summary(self.summary, self.checkpoints, self.seeds)

    def test_profiles_are_nested_in_thirty_equal_weight_histories(self):
        result = self.report()
        self.assertEqual(result["primary"]["n"],30)
        self.assertEqual(result["primary"]["df"],29)
        expected = []
        for h in self.summary["history_results"].values():
            p,e = h["branches"]["team_P"],h["branches"]["team_E"]
            expected.append(sum(x["cBR"]-y["cBR"] for x,y in zip(p["profiles"],e["profiles"]))/2)
        self.assertAlmostEqual(result["primary"]["mean"], sum(expected)/30,places=14)
        self.assertAlmostEqual(result["primary"]["sd"],float(np.std(expected,ddof=1)),places=14)
        self.assertEqual(len(result["histories"]),30)
        self.assertEqual(result["status"],"terminal_complete_study")

    def test_direction_alignment_does_not_cancel_complementary_profiles(self):
        result = self.report()
        directions = result["histories"][0]["aligned_shift"]["profiles"]
        self.assertEqual([x["direction"] for x in directions],[1,-1])
        self.assertGreater(result["aligned_shift_descriptive"]["mean"],0)
        self.assertIsNone(result["aligned_shift_descriptive"]["p_value"])
        self.assertIsNone(result["aa_repeatability_descriptive"]["p_value"])
        self.assertFalse(result["aa_repeatability_descriptive"]["equivalence_test_performed"])

    def test_failed_history_retained_and_contrast_specific_pairs_not_replaced(self):
        seed=str(self.seeds[0])
        self.summary["status"]="error"
        history=self.summary["history_results"][seed]
        history["status"]="error"
        history["error"]="fixture transport failure"
        p=history["branches"]["team_P"]
        p["profiles"].pop()
        p["complete"]=False
        p["mean_cBR"]=None
        result=self.report()
        self.assertEqual(result["primary"]["n"],29)
        self.assertEqual(result["primary"]["missing_history_ids"],[seed])
        self.assertEqual(result["exploratory_secondary_family"]["H_minus_E"]["n"],30)
        self.assertEqual(result["primary"]["all_planned_missing_bounds"]["missing_n"],1)
        self.assertEqual(len(result["histories"]),30)
        self.assertEqual(result["status"],"terminal_incomplete_complete_pair_analysis")

    def test_pending_histories_must_be_explicit_and_no_interim_inference(self):
        seed=str(self.seeds[-1])
        self.summary["status"]="running"
        self.summary["history_results"][seed]={"seed":int(seed),"status":"not_started","branches":{}}
        result=self.report()
        self.assertEqual(result["primary"]["n"],29)
        self.assertIsNone(result["primary"]["p_two_sided"])
        self.assertIsNone(result["primary_bootstrap_sensitivity"]["ci95"])
        self.assertEqual(result["status"],"interim_descriptive_only")
        del self.summary["history_results"][seed]
        with self.assertRaises(ValueError): self.report()

    def test_duplicate_seed_or_profile_cannot_inflate_sample(self):
        self.seeds[-1]=self.seeds[0]
        with self.assertRaises(ValueError): self.report()
        self.summary,self.checkpoints,self.seeds=fixture()
        branch=self.summary["history_results"][str(self.seeds[0])]["branches"]["team_P"]
        branch["profiles"].append(deepcopy(branch["profiles"][0]))
        with self.assertRaises(ValueError): self.report()

    def test_malformed_scores_probabilities_profiles_and_nan_rejected(self):
        for field,value in (("cBR",.999),("probability",float("nan")),("oracle_probability",.5),
                            ("profile_id","X100"),("signals",{"A":True,"B":0,"C":0})):
            summary,cp,seeds=fixture()
            summary["history_results"][str(seeds[0])]["branches"]["team_P"]["profiles"][0][field]=value
            with self.subTest(field=field),self.assertRaises(ValueError):
                analysis.analyze_summary(summary,cp,seeds)

    def test_completed_status_cannot_hide_missing_profiles(self):
        h=self.summary["history_results"][str(self.seeds[0])]
        h["branches"]["team_P"]["profiles"].pop()
        with self.assertRaises(ValueError): self.report()

    def test_file_reader_hashes_inputs_and_refuses_escaping_history_paths(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp)
            manifest={"protocol_version":analysis.PROTOCOL,
                      "config":{"protocol_version":analysis.PROTOCOL,"seeds":self.seeds}}
            for seed in self.seeds:
                relative=f"histories/{seed}/attempt_001"
                self.summary["history_paths"][str(seed)]=relative
                folder=root/relative;folder.mkdir(parents=True)
                (folder/"checkpoint.json").write_text(json.dumps(self.checkpoints[str(seed)]),encoding="utf-8")
            (root/"manifest.json").write_text(json.dumps(manifest),encoding="utf-8")
            (root/"summary.json").write_text(json.dumps(self.summary),encoding="utf-8")
            result=analysis.analyze(root)
            self.assertEqual(len(result["input_sha256"]),32)
            self.assertEqual(result["primary"]["n"],30)
            self.summary["history_paths"][str(self.seeds[0])]="../outside"
            (root/"summary.json").write_text(json.dumps(self.summary),encoding="utf-8")
            with self.assertRaises(ValueError):analysis.analyze(root)


if __name__ == "__main__":
    unittest.main()
